TP.register({id:"lp3-g3",lp:3,grade:"3",mode:"curriculum",checks:2,nextGrade:"4th grade",build(E){const F=E.F;const MAZE_TITLE="The Corn Maze";const MAZE=["The corn maze at Miller Farm had tall green walls and paths that twisted in every direction. Dev and his friend Rosa ran in at two o’clock. “We will be out in five minutes,” said Dev.","They turned left, then right, then left again. Every path looked the same. After a while, Rosa stopped. “We have passed this broken stalk three times,” she said. “We are going in circles.”","They stood still and listened. Somewhere off to the right a family was laughing, but the corn was so thick that the sound seemed to come from every side at once. Rosa pulled a leaf off the nearest stalk and dropped it on the path. “Now we will know if we come back here,” she said.","Dev frowned. He did not want to ask for help. Then he noticed something above the corn. It was the scarecrow’s red hat, far away by the gate.","“The scarecrow stands at the exit,” he said. “If we keep walking toward the hat, we will get out.”","The hat was easy to lose. Every time the path dipped, the corn closed over it, and they had to wait for the next rise to find it again.","At each turn, they looked up and picked the path that led toward the hat. Twice they hit a dead end and had to back up. At last the corn opened, and there was the gate.","Rosa checked the clock on the barn. It was three o’clock. “Five minutes?” she said, laughing. Dev grinned. “Next time, I will look up first.”"].join("\n\n");const WAGON_TITLE="The Biggest Pumpkin";const WAGON="Lena rode the harvest wagon past a sea of orange pumpkins. She picked the biggest one she could find. “This thing weighs a ton!” she groaned. Farmer Ortiz helped her roll it to the wagon. By sunset, Lena could not stop yawning. “It is time for you to hit the hay,” said Farmer Ortiz. Lena looked at the hay bales stacked by the barn. “Those hay bales?” she asked. He laughed. “No. I mean it is time for bed.”";const SUN_TITLE="Follow the Sun";const SUN=["A young sunflower does something surprising. It moves. In the morning, its bud faces east, where the sun comes up. All day, the bud slowly turns to follow the sun across the sky. By evening, it faces west. During the night, it swings back to the east and waits for morning.","Why does it do this? Facing the sun gives the young plant more light, and more light helps it grow faster.","When a sunflower is fully grown, it stops moving. The big yellow flower faces east for the rest of its life. Scientists found that flowers facing east warm up faster in the morning. Bees like warm flowers, so more bees visit them.","One sunflower head can hold more than 1,000 seeds. Birds, squirrels, and people all like to eat them."].join("\n\n");const PUMP_TITLE="Pumpkins";const PUMP="Pumpkin seeds are planted in late spring, when the soil is warm. The vines need plenty of sunshine and water. They also need room to spread out, because one vine can grow longer than a car. In fall, the pumpkins are ready, and people use them in many ways. Cooks bake pumpkin into pies, bread, and soup. The seeds can be roasted for a crunchy snack. Farmers feed extra pumpkins to pigs and chickens. Some people set whole pumpkins by the front door as a fall decoration.";const WORDS=["sunflower","scarecrow","preheat","misplace","thankful","darkness","disappear","enjoyment","washable","direction","unbreakable","rediscover"];const GREEN="#4E8B3A";const FONT=`font-family="Andika,sans-serif" font-weight="700"`;function pumpkinAt(x,y,r,fill){fill=fill||"var(--gold)";return`<rect x="${x-r*.1}" y="${y-r*1.05}" width="${r*.2}" height="${r*.35}" rx="2" fill="${GREEN}" stroke="var(--ink)" stroke-width="1.5"/><ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.78}" fill="${fill}" stroke="var(--gold-ink)" stroke-width="2.5"/><ellipse cx="${x}" cy="${y}" rx="${r*.5}" ry="${r*.78}" fill="none" stroke="var(--gold-ink)" stroke-width="2"/><line x1="${x}" y1="${y-r*.78}" x2="${x}" y2="${y+r*.78}" stroke="var(--gold-ink)" stroke-width="2"/>`}function pumpkin(size,fill){const r=size*.42;return`<svg viewBox="0 0 ${size} ${size}" width="${size}" role="img" aria-label="Pumpkin">${pumpkinAt(size/2,size*.56,r,fill)}</svg>`}function pumpkinRows(rows,cols){const c=50,W=cols*c+12,H=rows*c+12;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="${rows} rows of ${cols} pumpkins">`;for(let r=0;r<rows;r++)for(let k=0;k<cols;k++)s+=pumpkinAt(6+k*c+c/2,6+r*c+c/2+4,18);return s+"</svg>"}function areaGrid(cols,rows,split){const u=38,top=split?30:4,W=cols*u+8,H=rows*u+top+4;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Rectangle made of ${rows} rows of ${cols} unit squares">`;for(let x=0;x<cols;x++)for(let y=0;y<rows;y++)s+=`<rect x="${4+x*u}" y="${top+y*u}" width="${u}" height="${u}" fill="${split&&x>=split?"var(--gold)":"var(--sea-soft)"}" stroke="var(--ink)" stroke-width="2.5"/>`;if(split){s+=`<text x="${4+split*u/2}" y="22" font-size="20" ${FONT} fill="var(--ink)" text-anchor="middle">Part 1</text><text x="${4+split*u+(cols-split)*u/2}" y="22" font-size="20" ${FONT} fill="var(--ink)" text-anchor="middle">Part 2</text>`;s+=`<line x1="${4+split*u}" y1="${top-4}" x2="${4+split*u}" y2="${top+rows*u+2}" stroke="var(--ink)" stroke-width="6"/>`}return s+"</svg>"}function cellShape(cells){const u=38,cols=Math.max(...cells.map(c=>c[0]))+1,rows=Math.max(...cells.map(c=>c[1]))+1;let s=`<svg viewBox="0 0 ${cols*u+8} ${rows*u+8}" width="${cols*u+8}" role="img" aria-label="A shape made of ${cells.length} unit squares">`;cells.forEach(c=>{s+=`<rect x="${4+c[0]*u}" y="${4+c[1]*u}" width="${u}" height="${u}" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="2.5"/>`});return s+"</svg>"}function mazeShape(){const u=36,ox=54,oy=34,P=(x,y)=>`${ox+x*u},${oy+y*u}`;const t=(txt,x,y,a)=>`<text x="${ox+x*u}" y="${oy+y*u}" font-size="21" ${FONT} fill="var(--ink)" text-anchor="${a||"middle"}" dominant-baseline="central">${txt}</text>`;return`<svg viewBox="0 0 ${ox+7*u+70} ${oy+5*u+44}" width="${ox+7*u+70}" role="img" aria-label="An L shape with sides labeled 3 m, 3 m, 4 m, 2 m, 7 m, and 5 m"><polygon points="${P(0,0)} ${P(3,0)} ${P(3,3)} ${P(7,3)} ${P(7,5)} ${P(0,5)}" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4" stroke-linejoin="round"/>${t("3 m",1.5,-.45)}${t("5 m",-.25,2.5,"end")}${t("7 m",3.5,5.55)}${t("2 m",7.25,4,"start")}${t("4 m",5,2.55)}${t("3 m",3.25,1.5,"start")}</svg>`}function fenceRect(){return`<svg viewBox="0 0 400 190" width="400" role="img" aria-label="Rectangle 9 meters long with unknown width and area 63 square meters"><rect x="50" y="30" width="270" height="120" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4"/><text x="185" y="90" font-size="20" ${FONT} fill="var(--ink)" text-anchor="middle" dominant-baseline="central">Area: 63 square meters</text><text x="185" y="172" font-size="22" ${FONT} fill="var(--ink)" text-anchor="middle">9 m</text><text x="332" y="90" font-size="22" ${FONT} fill="var(--ink)" dominant-baseline="central">? m</text></svg>`}function seedSvg(){return`<svg viewBox="0 0 84 84" width="84" role="img" aria-label="Seed"><ellipse cx="42" cy="48" rx="13" ry="22" fill="var(--surface)" stroke="var(--gold-ink)" stroke-width="3" transform="rotate(25 42 48)"/></svg>`}function sproutSvg(){return`<svg viewBox="0 0 84 84" width="84" role="img" aria-label="Sprout"><line x1="8" y1="72" x2="76" y2="72" stroke="var(--gold-ink)" stroke-width="4" stroke-linecap="round"/><path d="M42 72 V40" stroke="${GREEN}" stroke-width="5" fill="none" stroke-linecap="round"/><ellipse cx="29" cy="34" rx="14" ry="8" fill="${GREEN}" transform="rotate(25 29 34)"/><ellipse cx="55" cy="34" rx="14" ry="8" fill="${GREEN}" transform="rotate(-25 55 34)"/></svg>`}function vineSvg(){let pet="";for(let k=0;k<5;k++){const a=k*72*Math.PI/180;pet+=`<ellipse cx="${62+Math.cos(a)*11}" cy="${30+Math.sin(a)*11}" rx="8" ry="8" fill="var(--gold)" stroke="var(--gold-ink)" stroke-width="1.5"/>`}return`<svg viewBox="0 0 110 84" width="110" role="img" aria-label="Vine with a flower"><path d="M4 70 C 24 40, 40 80, 58 56 S 90 60, 106 44" stroke="${GREEN}" stroke-width="5" fill="none" stroke-linecap="round"/><ellipse cx="24" cy="52" rx="12" ry="8" fill="${GREEN}"/><ellipse cx="88" cy="62" rx="12" ry="8" fill="${GREEN}"/>${pet}<circle cx="62" cy="30" r="6" fill="var(--gold-ink)"/></svg>`}function growChart(){const it=(svg,t)=>`<div style="text-align:center;max-width:150px"><div style="height:96px;display:flex;align-items:flex-end;justify-content:center">${svg}</div><p class="fig-label" style="margin:2px 0 0;font-size:1.05rem">${t}</p></div>`;const arrow=`<span aria-hidden="true" style="font-size:1.8rem;font-weight:700;color:var(--muted);align-self:center">&rarr;</span>`;return`<div class="figure" style="gap:6px;align-items:flex-start">${[it(seedSvg(),"1. A seed goes into warm soil"),it(sproutSvg(),"2. A sprout comes up"),it(vineSvg(),"3. A long vine grows flowers"),it(pumpkin(60,GREEN),"4. A small green pumpkin starts"),it(pumpkin(96),"5. The pumpkin gets big and ripe")].join(arrow)}</div>`}function group(inner,label){return`<div style="text-align:center"><div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center;align-items:center">${inner}</div><p class="fig-label" style="margin:4px 0 0">${label}</p></div>`}function noteBoxes(a,b){const bx=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:270px;min-height:100px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.4rem">${t}</p></div>`;return`<div class="figure">${bx(a)}${bx(b)}</div>`}const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const pills=items=>`<div class="row center" style="margin-top:20px;gap:18px;flex-wrap:wrap">${items.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const L_CELLS=[];for(let y=0;y<3;y++)for(let x=0;x<2;x++)L_CELLS.push([x,y]);for(let y=3;y<5;y++)for(let x=0;x<6;x++)L_CELLS.push([x,y]);const SEED_A_TITLE="From the Farm Notebook";const SEED_A="We plant our sunflower seeds in May, once the nights stay warm. By late summer each flower head holds more than 1,000 seeds. We keep some seeds to plant again. The rest are pressed into cooking oil.";const SEED_B_TITLE="From the Bird Club Notes";const SEED_B="Sunflower seeds are a favorite food of birds. One flower head holds more than 1,000 seeds, so a single plant can feed a flock for days. Chickadees crack the shells open and drop the empty husks on the ground.";const MAZE_MADE="Here is how Miller Farm builds its corn maze. Long before fall, the farmer draws the whole maze on paper, path by path. In late spring, when the corn is only ankle high, a small machine drives through the field and cuts the paths, following the drawing. All summer the corn grows up around those open paths. By the time the first visitors arrive, the walls are taller than a grown-up.";function fracLine(d,markNum){const w=640,x0=60,x1=580,y=64,step=(x1-x0)/d;let s=`<svg viewBox="0 0 ${w} 116" width="${w}" role="img" aria-label="A number line from 0 to 1 cut into ${d} equal parts, with a dot on one of the marks">`;s+=`<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="var(--ink)" stroke-width="3"/>`;for(let i=0;i<=d;i++){const x=x0+i*step;s+=`<line x1="${x}" y1="${y-14}" x2="${x}" y2="${y+14}" stroke="var(--ink)" stroke-width="${i===0||i===d?4:2.5}"/>`}s+=`<text x="${x0}" y="${y+44}" font-size="24" ${FONT} fill="var(--ink)" text-anchor="middle">0</text>`;s+=`<text x="${x1}" y="${y+44}" font-size="24" ${FONT} fill="var(--ink)" text-anchor="middle">1</text>`;s+=`<circle cx="${x0+markNum*step}" cy="${y}" r="10" fill="var(--coral)" stroke="var(--ink)" stroke-width="2.5"/>`;return s+"</svg>"}function linePlot(labels,counts){const w=660,base=182,x0=80,step=118;let s=`<svg viewBox="0 0 ${w} 230" width="${w}" role="img" aria-label="A line plot of stem lengths in inches">`;s+=`<text x="${w/2}" y="24" font-size="21" ${FONT} fill="var(--ink)" text-anchor="middle">Pumpkin Stem Lengths (inches)</text>`;s+=`<line x1="40" y1="${base}" x2="${w-30}" y2="${base}" stroke="var(--ink)" stroke-width="3"/>`;labels.forEach((t,i)=>{const x=x0+i*step;s+=`<line x1="${x}" y1="${base-8}" x2="${x}" y2="${base+8}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<text x="${x}" y="${base+32}" font-size="20" ${FONT} fill="var(--ink)" text-anchor="middle">${t}</text>`;for(let k=0;k<counts[i];k++)s+=`<text x="${x}" y="${base-20-k*26}" font-size="22" ${FONT} fill="var(--sea)" text-anchor="middle">X</text>`});return s+"</svg>"}const STOPS=[{id:1,title:"Sunflower Words",short:"Sun Words",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:75,dir:"Read each word out loud. Look for a part you know at the start or the end of the word.",desc:"reading longer words with prefixes and suffixes",key:["Read each word: sunflower, scarecrow, preheat, misplace, thankful, darkness, disappear, enjoyment, washable, direction, unbreakable, rediscover.","Watch for: compound words (sunflower, scarecrow), prefixes pre-, mis-, dis-, un-, re- (preheat, misplace, disappear, unbreakable, rediscover), suffixes -ful, -ness, -ment, -able (thankful, darkness, enjoyment, washable, unbreakable), the Latin suffix -tion (direction), and words with three or four syllables.","Optional check of word parts: ask what mis- means in misplace (wrong, so to put in the wrong place) and what -able means in washable (can be washed)."]}]},{id:2,title:"Pumpkin Weigh-In",short:"Weigh-In",parts:[{std:["3.NBT.A.1"],dur:105,dir:"Say each answer out loud.",desc:"rounding whole numbers to the nearest 10 and 100",fig:()=>F.row([F.numberLine({min:40,max:50,step:1,labelEvery:10,marks:[43],width:560}),"Number line for number 1"]),qs:["The dot is at 43. Which ten is 43 closer to? Round 43 to the nearest ten.","Round 78 to the nearest ten.","Round 265 to the nearest ten.","Round 529 to the nearest hundred.","Round 961 to the nearest hundred.","A sign says a pumpkin weighs about 40 pounds. The weight was rounded to the nearest ten. Could the pumpkin weigh 35 pounds? 44 pounds? 46 pounds? Tell how you know."],key:["43 is closer to 40, so it rounds to 40. Partial: 50 rounds up when 43 sits below the halfway mark and does not count. (3.NBT.A.1)","80. Partial: 70 rounds down when the ones digit is 8 and does not count. (3.NBT.A.1)","270. A 5 in the ones place rounds up. Partial: 260 rounds down at the halfway mark and does not count. (3.NBT.A.1)","500. Partial: 600 rounds up when the tens digit is 2 and does not count. (3.NBT.A.1)","1,000. 961 is between 900 and 1,000 and is closer to 1,000. Partial: 900 rounds down when 961 is past the halfway mark and does not count. (3.NBT.A.1)","35 yes, 44 yes, 46 no. 35 and 44 both round to 40, but 46 rounds to 50. All three are needed. Partial: two of the three answered right is approaching. (3.NBT.A.1)"]}]},{id:3,title:"Into the Corn Maze",short:"Maze Read",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>F.passage(MAZE,MAZE_TITLE),key:["__WC__ words, not counting the title. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Fall grade 3 benchmark: about 83 words correct per minute (Hasbrouck and Tindal 2017, fall 50th percentile). The passage length is set from the highest grade 3 figure on that same table, the spring 90th percentile of about 166 words correct per minute, so the minute ends before the text does even for the fastest reader and the score measures the reading rather than the length of the page.","Note pace, phrasing, and expression. Listen for the question in Rosa’s voice at “Five minutes?”"]}]},{id:4,title:"Maze Questions",short:"Maze Qs",parts:[{std:["RL.3.1"],dur:150,dir:"Read the story. Then answer out loud. Look back at the story to prove each answer.",desc:"asking and answering story questions using the exact words in the text",html:()=>F.passage(MAZE,MAZE_TITLE,true),qs:["How did Rosa know they were going in circles? Which sentence tells you?","What did Dev use to find the way out? Why did it work? Use the story.","How long were Dev and Rosa in the maze? Find the two sentences that help you know.","Your turn to be the teacher. Ask one question that this story answers. Start with Who, Why, or How."],key:["They kept passing the same broken stalk. Points to “We have passed this broken stalk three times.” (RL.3.1)","The scarecrow’s red hat. It worked because the scarecrow stands at the exit and the hat shows above the corn, so walking toward the hat leads out. (RL.3.1)","One hour. Points to “ran in at two o’clock” and “It was three o’clock.” (RL.3.1)","Asks a question the story can answer, such as: Why did Rosa laugh? How did they get out? Who saw the red hat? (RL.3.1, asks questions)"]}]},{id:5,title:"Hay Bale Floors",short:"Barn Floors",parts:[{std:["3.MD.C.7"],dur:135,dir:"Look at the pictures. Answer out loud. Tell how you know.",desc:"finding area by counting squares, adding parts, and multiplying side lengths",fig:()=>`<div class="figure" style="gap:30px;align-items:flex-end">${group(areaGrid(7,3),"Picture A: barn floor")}${group(areaGrid(9,4,5),"Picture B: floor in two parts")}${group(F.rect(9,6,"m"),"Picture C: pumpkin patch")}</div>`,qs:["Picture A: Each small square is 1 square unit. What is the area of the barn floor? Tell two ways to find it.","Picture B: Find the area of Part 1 and the area of Part 2. Then find the area of the whole floor.","Picture C: The pumpkin patch is 9 meters long and 6 meters wide. What is its area?","One rectangle is 2 units by 10 units. Another is 4 units by 5 units. True or false: they have the same area. Tell why."],key:["21 square units. Two ways, such as counting every square, adding the rows 7 + 7 + 7, or multiplying 3 × 7. Partial: the area right with only one way given is approaching. (3.MD.C.7)","Part 1 is 4 × 5 = 20 square units. Part 2 is 4 × 4 = 16 square units. The whole floor is 20 + 16 = 36 square units, the same as 4 × 9. Partial: the two parts right with no total given is approaching. (3.MD.C.7)","54 square meters, from 9 × 6. Partial: 30 meters from adding the sides gives the perimeter and does not count. (3.MD.C.7)","True. 2 × 10 = 20 and 4 × 5 = 20, so both are 20 square units. Partial: saying true with only one area worked out is approaching. (3.MD.C.7)"]}]},{id:6,title:"Hay Wagon Sayings",short:"Wagon Sayings",parts:[{std:["RL.3.4"],dur:80,dir:"Read the story. Then answer out loud.",desc:"literal and nonliteral meanings of phrases in a story",html:()=>F.passage(WAGON,WAGON_TITLE,true),qs:["The story says “a sea of orange pumpkins.” Is there real water in the pumpkin patch? What does the phrase tell you?","Lena says, “This thing weighs a ton!” Does the pumpkin really weigh a ton? What does she mean?","Farmer Ortiz says it is time to “hit the hay.” What did Lena think he meant? What did he really mean?","Find one sentence in the story that means exactly what it says."],key:["No. It means there are so many pumpkins that they spread out as far as she can see, like a sea. (RL.3.4)","No. She means it is very heavy. (RL.3.4)","Lena thought he meant the real hay bales by the barn, which is the literal meaning. He meant it was time to go to bed, which is the nonliteral meaning. (RL.3.4)","Any literal sentence, such as “She picked the biggest one she could find,” “Farmer Ortiz helped her roll it to the wagon,” or “Lena looked at the hay bales stacked by the barn.” Not the sea, ton, or hit the hay sentences. (RL.3.4)"]}]},{id:7,title:"Harvest Wagon Loads",short:"Wagon Loads",parts:[{std:["3.OA.D.8"],n:4,dur:150,dir:"Solve on your paper. Show your work and hold it up.",desc:"two-step word problems solved with an equation that uses a letter",fig:()=>`<div class="figure">${group(pumpkinRows(4,5),"The wagon in problem 1, before any pumpkins roll off")}</div>`,qs:["A wagon has 4 rows of pumpkins with 5 pumpkins in each row. Then 6 pumpkins roll off. How many pumpkins are still on the wagon? Write an equation with a letter for the number you do not know. Then solve.","Omar picks 18 small pumpkins and 12 big pumpkins. He packs all of them into crates with 5 pumpkins in each crate. How many crates does he fill? Write an equation with a letter. Then solve."],key:["Problem 1 equation with a letter, such as 4 × 5 − 6 = p, or 4 × 5 = 20 and 20 − 6 = p. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 1 answer: 14 pumpkins. Partial: 20 stops at the rows and leaves the 6 out, so it is approaching. (3.OA.D.8)","Problem 2 equation with a letter, such as (18 + 12) ÷ 5 = c, or 18 + 12 = 30 and 30 ÷ 5 = c. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 2 answer: 6 crates. Partial: 30 stops at the total and leaves the crates out, so it is approaching. (3.OA.D.8)"]}]},{id:8,title:"Scarecrow Says",short:"Scarecrow",parts:[{title:"Mixed-Up Scarecrow",std:["L.3.1"],dur:70,dir:"The scarecrow mixed up his words. Each sentence has one mistake. Say the whole sentence the right way.",desc:"fixing spoken grammar mistakes (plurals, verb tense, agreement, comparing words, pronouns)",qs:["The geeses flew over the corn.","My friends likes the hay ride.","Last week we buyed three pumpkins.","This is the most biggest sunflower in the field.","The children left its boots by the barn."],key:["The geese flew over the corn. (L.3.1, irregular plural noun)","My friends like the hay ride. (L.3.1, subject-verb agreement)","Last week we bought three pumpkins. (L.3.1, irregular past tense verb)","This is the biggest sunflower in the field. (L.3.1, superlative adjective)","The children left their boots by the barn. (L.3.1, pronoun that matches its noun)"]},{title:"Hay Bale Builder",std:["L.3.1"],dur:65,dir:"Answer out loud. Say whole sentences.",desc:"spoken grammar items (joining sentences, past tense, comparing words, abstract nouns)",qs:["Join these two sentences into one. Use so or because: The wagon was full. We walked back.","Change this sentence so it happened yesterday: The farmer drives the wagon. We sing.","Finish it: This pumpkin is heavy. That one is heavier. The giant one is the ____ of all.","Which word names something you cannot see or touch: wagon, kindness, or pumpkin?"],key:["The wagon was full, so we walked back. Or: We walked back because the wagon was full. (L.3.1, conjunctions and compound or complex sentences)","The farmer drove the wagon, and we sang. Both verbs are needed. (L.3.1, irregular past tense verbs)","heaviest (L.3.1, superlative adjective)","kindness (L.3.1, abstract noun)"]}]},{id:9,title:"Follow the Sun",short:"Sunflowers",parts:[{std:["RI.3.1"],dur:135,dir:"Read the text. Then answer out loud. Look back at the text to prove each answer.",desc:"questions about an informational text answered with the exact words in the text",html:()=>F.passage(SUN,SUN_TITLE,true),qs:["Which way does a young sunflower face in the morning? Read the sentence that tells you.","Why does a young sunflower follow the sun? Which sentence tells you?","How is a fully grown sunflower different from a young one? Use the text.","Why do more bees visit flowers that face east? Find the two sentences that explain it."],key:["East. Reads “In the morning, its bud faces east, where the sun comes up.” (RI.3.1)","To get more light so it can grow faster. Points to “Facing the sun gives the young plant more light, and more light helps it grow faster.” (RI.3.1)","A young sunflower turns to follow the sun. A fully grown sunflower stops moving and faces east for the rest of its life. (RI.3.1)","Flowers that face east warm up faster in the morning, and bees like warm flowers. Points to the last two sentences of the third paragraph. (RI.3.1)"]}]},{id:10,title:"Patch Plans",parts:[{std:["3.MD.C.7"],dur:120,dir:"Look at the pictures. Solve on your paper and hold it up. Then tell how you did it.",desc:"finding the area of shapes made of two rectangles by adding the parts",fig:()=>`<div class="figure" style="gap:40px;align-items:flex-end">${group(cellShape(L_CELLS),"Picture A: sunflower garden")}${group(mazeShape(),"Picture B: corn maze")}</div>`,qs:["Picture A: Each small square is 1 square unit. Break the garden into two rectangles. What is the area of the whole garden?","Picture B: This corn maze has no squares to count. Break it into two rectangles and find its area.","Spot the mistake. Milo says a square with sides of 5 units has an area of 10 square units. That is because 5 + 5 = 10. What did Milo do wrong? What is the area?"],key:["18 square units. Two rectangles, such as 2 × 3 = 6 and 6 × 2 = 12, or 2 × 5 = 10 and 4 × 2 = 8. Partial: the two rectangles right with no total given is approaching. (3.MD.C.7)","23 square meters. Two rectangles, such as 3 × 5 = 15 and 4 × 2 = 8, or 7 × 2 = 14 and 3 × 3 = 9. Partial: the two rectangles right with no total given is approaching. (3.MD.C.7)","Milo added two sides. Area is rows times columns, so the area is 5 × 5 = 25 square units. Partial: naming the mistake with no area given is approaching. (3.MD.C.7)"]}]},{id:11,title:"Patch Writer",short:"Write",parts:[{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"Teach how a pumpkin grows"},std:["W.3.2"],n:4,label:"checks met",dur:270,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone how a pumpkin grows. Use the picture chart. Write 5 or 6 sentences.</p>${growChart()}${checklist(["Start with a sentence that names your topic","Tell the steps as facts, and add a detail to at least one step","Use linking words: first, next, also, after that","End with a closing sentence"])}`,key:["Introduces the topic: how a pumpkin grows (W.3.2)","Develops the topic with facts from the chart in order (seed in warm soil, sprout, vine with flowers, small green pumpkin, big ripe pumpkin) and adds at least one detail (W.3.2)","Uses linking words such as first, next, also, another, after that (W.3.2)","Ends with a concluding sentence (W.3.2)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"Your pumpkin is too big for the wagon"},std:["W.3.3"],n:4,label:"checks met",dur:270,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"a narrative writing piece",html:()=>`<p class="big">You grow a pumpkin so big that it will not fit in the harvest wagon. Write the story of how you get it home. Write 5 or 6 sentences.</p>${pills(["First","Next","After that","Finally"])}${checklist(["Tell who is in the story and where it happens","Tell what happens in order","Add a detail that helps the reader picture it, and tell what someone says or feels","Give your story an ending"])}`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words such as first, next, after that, finally (W.3.3)","Uses descriptive details and tells thoughts or feelings, or uses dialogue (W.3.3)","Has an ending that wraps up the story (W.3.3)"]}]},{id:12,title:"Does It Make Sense?",short:"Make Sense?",parts:[{std:["3.OA.D.8"],dur:105,dir:"Estimate first. Then solve on your paper and hold it up.",desc:"estimating and checking whether answers to two-step problems make sense",qs:["On Saturday, 287 people came to the pumpkin patch. On Sunday, 412 people came. Of all those people, 95 rode the hay wagon. About how many people did not ride the wagon? Round each number to estimate. Do not find the exact answer yet.","Now find the exact answer. Is it close to your estimate?","Spot the mistake. A farm had 150 ears of corn. It sold 48 ears on Monday and 52 ears on Tuesday. Milo says 250 ears are left. Does his answer make sense? Tell why. Then find the right answer."],key:["About 600 people, from 300 + 400 − 100. Partial: any rounding that lands near 600 counts, and the exact answer alone is approaching, since an estimate was asked for. (3.OA.D.8, estimates by rounding)","604 people. 287 + 412 = 699, then 699 − 95 = 604. Yes, 604 is close to 600. Partial: 699 stops before the wagon riders are taken off and is approaching. (3.OA.D.8)","No. The farm sold corn, so the answer has to be less than 150. Milo added when he should have subtracted. 48 + 52 = 100, and 150 − 100 = 50 ears left. Partial: saying no with no right answer given is approaching. (3.OA.D.8, checks if an answer is reasonable)"]}]},{id:13,title:"Pumpkin Notes",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:120,dir:"Read the text. Write your notes on your paper and hold it up.",desc:"taking brief notes from a text and sorting them into given categories",html:()=>`${F.passage(PUMP,PUMP_TITLE,true)}<p class="big">Make two boxes on your paper. Label them like the boxes below. Write two short notes from the text in each box.</p>${noteBoxes("What pumpkin plants need","How people use pumpkins")}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Needs box: two facts, such as warm soil, sunshine, water, room to spread out. (W.3.8, sorts evidence into the given category)","Uses box: two facts, such as pies, bread, and soup, roasted seeds for a snack, food for pigs and chickens, a fall decoration. (W.3.8, sorts evidence into the given category)","Notes are brief: a few words or a short phrase, not a whole sentence copied from the text. (W.3.8, brief notes)"]}]},{id:14,title:"Scarecrow Talk",short:"Talk",parts:[{std:["SL.3.4"],n:3,label:"checks met",dur:90,dir:"Pick A or B. Talk for about one minute. Speak clearly, and do not rush.",desc:"telling about an experience or a topic with facts and details, speaking clearly",html:()=>`<div class="figure" style="gap:24px;align-items:stretch"><div style="border:4px solid var(--line);border-radius:18px;padding:14px 20px;max-width:420px;background:var(--surface)"><p class="big" style="margin:0">A: Tell about the best day you ever spent outside.</p></div><div style="border:4px solid var(--line);border-radius:18px;padding:14px 20px;max-width:420px;background:var(--surface)"><p class="big" style="margin:0">B: Teach me about a food you know how to make.</p></div></div>${pills(["Say your topic","Give 3 facts or details","Tell what you saw, heard, or felt"])}`,key:["Gives facts that fit the topic or the experience (SL.3.4)","Adds relevant, descriptive details, such as what it looked, sounded, or felt like (SL.3.4)","Speaks clearly at a pace you can follow (SL.3.4)"]}]},{id:15,title:"The Better Job",short:"Opinion",parts:[{std:["W.3.1"],n:4,label:"checks met",dur:60,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"a short opinion piece with reasons, linking words, and a closing",html:()=>`<p class="big">Miller Farm needs help this fall. Which job would you rather have: riding the wagon out to pick pumpkins, or working the gate where visitors come in?</p><p class="big">Write 4 sentences. Say which job you pick, give two reasons, and end with a closing sentence.</p>${pills(["I would rather","because","Another reason","That is why"])}`,key:["Names the topic and states an opinion, such as: I would rather work the gate. (W.3.1)","Gives two reasons that support the opinion, not two ways of saying the same thing. (W.3.1)","Uses a linking word or phrase such as because, also, another reason, or since. (W.3.1)","Ends with a concluding sentence, such as: That is why the gate is the better job. (W.3.1)"]}]},{id:16,title:"Two Looks at One Seed",short:"Two Texts",parts:[{std:["RI.3.9"],n:3,dur:50,dir:"Read both short texts. Then answer out loud.",desc:"comparing the key points of two texts on the same topic",html:()=>`${F.passage(SEED_A,SEED_A_TITLE,true)}${F.passage(SEED_B,SEED_B_TITLE,true)}`,key:["Ask: What point do both texts make about one sunflower head? (It holds more than 1,000 seeds. Both texts say it.) (RI.3.9)","Ask: What does the Farm Notebook tell you that the Bird Club Notes do not? (The seeds are planted in May, some are kept to plant again, and the rest are pressed into cooking oil. Any one of these counts.) (RI.3.9)","Ask: Both texts are about sunflower seeds. How is the main point of each one different? (The Farm Notebook is about growing the seeds and what farmers do with them. The Bird Club Notes are about birds eating them.) (RI.3.9)"]}]},{id:17,title:"How the Maze Is Made",short:"Listen",parts:[{std:["SL.3.2"],n:3,dur:45,sup:true,read:MAZE_MADE,dir:"Listen while your teacher reads. The words are not on your screen. Then answer out loud.",desc:"main idea and supporting details of a text read aloud",fig:()=>`<div class="figure">${F.pic("corn","","4.5rem")}</div>`,key:["Read the text out loud once. Read it a second time only if the student asks.","Ask: What is the main idea? (How Miller Farm builds its corn maze: the whole maze is planned and cut long before fall.) (SL.3.2)","Ask: Give me two details that go with that main idea. (The farmer draws the maze on paper first. A machine cuts the paths when the corn is ankle high. The corn grows up around the paths all summer. By fall the walls are taller than a grown-up. Any two count.) (SL.3.2)","Ask: What happens first, before anything is cut? (The farmer draws the whole maze on paper.) (SL.3.2)"]}]},{id:18,title:"Crates and Rows",short:"Crates",parts:[{title:"What a Product Means",std:["3.OA.A.1"],n:3,dur:65,dir:"Look at the crate. Answer out loud. You can write on your paper.",desc:"telling what a product means as a number of equal groups",fig:()=>`<div class="figure">${group(pumpkinRows(3,7),"Crate A")}</div>`,qs:["Crate A holds 3 rows with 7 pumpkins in each row. Write the multiplication fact. Then tell me what 3 x 7 means in this crate.","Tell me a patch story for 5 x 6. What does each number stand for in your story?","A wagon holds 9 pumpkins. There are 4 wagons. Write the multiplication fact. What does the 4 stand for, and what does the 9 stand for?"],key:["3 x 7 = 21. It means 3 groups with 7 pumpkins in each group, which is 21 pumpkins in all. The number of pumpkins in all is the key part. Partial: the fact right with no meaning given is approaching. (3.OA.A.1)","A story with 5 equal groups of 6, or 6 equal groups of 5, 30 pumpkins in all, such as 5 wheelbarrows with 6 pumpkins in each. The student has to say which number is the groups and which is how many are in one group. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.1)","4 x 9 = 36. The 4 is the number of wagons, which is the number of groups, and the 9 is the pumpkins in each wagon, which is how many are in one group. Or: 9 x 4 = 36 counts as well, as long as the student says which number is the groups and which is the size of a group. Partial: 36 right with no meaning given for the 4 and the 9 is approaching. (3.OA.A.1)"]},{title:"What a Quotient Means",std:["3.OA.A.2"],n:3,dur:60,dir:"Answer out loud. Tell me what the answer counts. You can write on your paper.",desc:"telling what a quotient means, as the size of each share and as the number of shares",qs:["24 pumpkins go into 4 crates with the same number in each crate. Write the division fact. Then tell me what 24 divided by 4 means.","Now a different story with the same two numbers. 24 pumpkins go into crates with 4 pumpkins in each crate. What does 24 divided by 4 tell you this time?","35 pumpkins are set out in rows of 7. Does 35 divided by 7 give you the number of rows or the number in each row? Say how you know."],key:["24 divided by 4 = 6. It means 24 pumpkins split into 4 equal groups, with 6 in each group. Saying it the other way, how many are in each of the 4 crates, also counts. Partial: the fact right with no meaning given is approaching. (3.OA.A.2)","6 again, but this time the 6 is the number of crates, not the number in each crate. The size of each share is the number given here, so the answer counts the shares. Partial: 6 right with nothing said about what it counts is approaching, and saying the 6 is pumpkins in a crate does not count. (3.OA.A.2)","The number of rows, 5. The story gives 7 as the number in each row, so the answer counts the rows. Partial: 5 right with no account of which of the two it counts is approaching, and naming it as the number in each row does not count. (3.OA.A.2)"]}]},{id:19,title:"Fraction Field",short:"Fractions",parts:[{title:"Equal Parts",std:["3.G.A.2","3.NF.A.1"],n:3,dur:50,dir:"Look at the two pictures. Answer out loud.",desc:"naming the unit fraction for one equal part of a shape and reading a fraction of a whole",fig:()=>F.row([F.gridRect(1,6,3,{cell:56}),"Picture 1: a garden bed"],[F.fracCircle(4,1,150),"Picture 2: a round sign"]),qs:["Picture 1 is a garden bed cut into 6 equal parts. What fraction of the whole bed is one part?","What fraction of the bed is shaded? Tell me what the top number means and what the bottom number means.","Picture 2 is cut into 4 equal parts. What fraction of the sign is shaded?"],key:["1/6. One of 6 equal parts of the whole bed. Partial: 6 given with no fraction form is approaching. (3.G.A.2)","3/6. The 6 is how many equal parts the whole is cut into. The 3 is how many of those parts are counted. Partial: the fraction right with only one of the two numbers explained is approaching. (3.NF.A.1)","1/4. Partial: 4 given with no fraction form is approaching. (3.NF.A.1)"]},{title:"On the Line",std:["3.NF.A.2"],n:3,dur:70,dir:"Look at the number line. Answer out loud.",desc:"placing and naming a fraction on a number line",fig:()=>F.row(fracLine(4,3)),qs:["The line from 0 to 1 is cut into 4 equal parts. What fraction does one of those parts show?","What fraction is the dot sitting on? How do you know?","Nothing is marked at 1/2 on this line. Point to where 1/2 sits. Then tell me how you know that is the spot."],key:["1/4. The whole from 0 to 1 is cut into 4 equal lengths, so one length is 1/4. Partial: 1/4 right with no account of the equal lengths is approaching. (3.NF.A.2)","3/4. It is 3 of those 1/4 lengths away from 0. Partial: 3/4 right with no count of lengths from 0 is approaching. (3.NF.A.2)","Points to the middle tick, the one 2 of the 4 equal lengths from 0, and says that 2 of the 4 lengths is half the whole, so 1/2 and 2/4 are the same point on this line. Partial: pointing to the right tick with no account of the two equal lengths, or saying 2/4 without pointing, is approaching. Pointing to the 1 at the end, or to the first tick, does not count. (3.NF.A.2)"]},{title:"Same or Not",std:["3.NF.A.3"],n:3,dur:45,dir:"Look at the two bars. They are the same length. Answer out loud.",desc:"equivalent fractions and comparing fractions with the same numerator or the same denominator",fig:()=>F.row([F.fracBar(2,1,{width:320}),"Bar 1"],[F.fracBar(4,2,{width:320}),"Bar 2"]),qs:["Bar 1 shows 1/2 shaded and Bar 2 shows 2/4 shaded. Is 1/2 equal to 2/4? How do you know?","Which is greater, 3/4 of a bar or 1/4 of the same bar? How do you know?","Two gardens are the same size. One is 2/3 full of pumpkins. The other is 2/6 full. Which garden has more pumpkins? How do you know?"],key:["Yes, they are equal. The bars are the same length and the same amount is shaded. Partial: saying yes with no reason from the bars is approaching. (3.NF.A.3)","3/4. The pieces are the same size, and 3 pieces is more than 1 piece. Partial: naming 3/4 with no reason is approaching. (3.NF.A.3)","The 2/3 garden. Thirds are bigger pieces than sixths, so 2 thirds covers more than 2 sixths. Partial: naming the 2/3 garden with no reason about the size of the pieces is approaching. (3.NF.A.3)"]}]},{id:20,title:"Measure the Stems",short:"Line Plot",parts:[{std:["3.MD.B.4"],n:5,dur:115,dir:"Look at the line plot. Each X is one pumpkin stem. Answer out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"reading and adding to a line plot of lengths measured to the half inch, and generating measurements of real objects with a ruler",fig:()=>F.row(linePlot(["2","2 1/2","3","3 1/2","4"],[1,3,2,4,1])),qs:["How many stems were exactly 3 inches long?","Which length came up the most?","How many stems were measured in all?","One more stem is measured with a ruler. It is 2 1/2 inches. Where does its X go? How many Xs are above that mark then?","Now you are the measurer. Find three small things at your table. Something like a pencil. Or an eraser. Or a paper clip. Measure each one with your ruler. Say what each thing is. Say how long it is, to the nearest quarter inch."],key:["2 stems. Partial: counting the Xs above a different mark does not count. (3.MD.B.4)","3 1/2 inches, with 4 Xs. Partial: the length right with no count of Xs is approaching. (3.MD.B.4)","11 stems (1 + 3 + 2 + 4 + 1). Partial: four of the five stacks counted is approaching. (3.MD.B.4)","The X goes above the 2 1/2 mark, on top of the ones already there. That makes 4 Xs above 2 1/2. Partial: the mark right with no new count of Xs is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet, and have the student hold one object on the ruler up to the camera so you can check that reading yourself. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)"]}]},{id:21,title:"Night Ears",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper and hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">A barn owl sits still on a beam above the straw. Something rustles below. She tips her head one way, then the other, then drops straight down.</p>
     <div class="figure">${F.icon("owl",96)}${F.icon("ear",80)}${F.icon("mouse",88)}</div>`,qs:["Which sense took in the information about the mouse? Which body part did that work?","Why did the owl tip her head twice before she dropped? What was going on inside her?","Draw the path the information took, from the straw to the drop. Label each part."],key:["Hearing, with her ears. The rustle is a sound. (3-LS1-1)","Her brain was working out where the sound was coming from. Turning her head gave the brain a second helping of information to compare, and then it decided where to drop. (3-LS1-1)","Three parts in order with arrows: ears or hears the rustle, then brain, then drops down. The order is what is rated. A model that goes straight from ears to dropping, with no brain in the middle, is incomplete. (3-LS1-1)"]},{title:"Many Eyes Are Better",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">Crows feed in the stubble beside the patch. A class watched single crows and flocks of crows for the same number of hours.</p>
     <table class="bigTable"><tr><th>Crows</th><th>Seconds spent head-up watching, out of every minute</th><th>Times surprised by a hawk</th></tr>
     <tr><td>one crow feeding alone</td><td>34</td><td>6</td></tr>
     <tr><td>a flock of twelve crows</td><td>9</td><td>1</td></tr></table>`,qs:["Which crows spent more of every minute watching instead of eating?","Make an argument that feeding in a flock helps a crow survive. Use a number from the table.","Name another way living in a group could keep an animal alive."],key:["the crow feeding alone, 34 seconds out of 60 against 9 (3-LS2-1)","The claim yes, with the numbers attached: a crow in the flock only watched for 9 seconds a minute, so it had more time to eat, and flocks were surprised once against six times. A yes with no number is not yet an argument. (3-LS2-1)","Any sound second reason: warning calls, chasing a predator off together, finding food faster with more searchers, help raising young, sharing warmth. (3-LS2-1)"]}]},{id:22,title:"Vines and Their Young",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a deeply ribbed orange pumpkin and five pumpkins grown from its seeds.</p>
     <table class="bigTable"><tr><th>Pumpkin</th><th>Skin</th><th>Weight in kg</th></tr>
     <tr><td>parent</td><td>orange, deep ribs</td><td>7</td></tr>
     <tr><td>A</td><td>orange, deep ribs</td><td>5</td></tr><tr><td>B</td><td>orange, deep ribs</td><td>8</td></tr>
     <tr><td>C</td><td>orange, deep ribs</td><td>6</td></tr><tr><td>D</td><td>orange, deep ribs</td><td>9</td></tr>
     <tr><td>E</td><td>orange, deep ribs</td><td>6</td></tr></table>
     <p class="big">Table 2: two vines grown from seeds out of the same pumpkin, planted the same week.</p>
     <table class="bigTable"><tr><th>Vine</th><th>Water it got</th><th>Longest vine</th><th>Pumpkins</th></tr>
     <tr><td>vine 1</td><td>watered every third day</td><td>4 m</td><td>6</td></tr>
     <tr><td>vine 2</td><td>rain only, in a dry corner</td><td>1 m</td><td>1</td></tr></table>`,qs:["Every pumpkin in Table 1 is orange with deep ribs, the same as the parent. Where did that come from?","The weights are all different. What is that difference called. Does it mean one of them grew from a different parent?","In Table 2, both seeds came out of the same pumpkin. What made one vine reach 4 m and the other only 1 m?","So is vine length decided only by the seed it came from? Explain."],key:["It was inherited from the parent plant. A trait the parent has and every offspring has is passed down. (3-LS3-1)","Variation. They all still grew from that parent: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","How much water each one got. Same parent pumpkin, different surroundings, different vine. (3-LS3-2)","No. The environment shaped it too. Listen for the idea that a trait can be influenced by where a living thing grows, not by inheritance alone. (3-LS3-2)"]}]},{id:23,title:"Stone and Survival",short:"Fossils",parts:[{title:"Clues in the Road Cut",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">A new road was cut through the ridge above the patch, and the cut shows three layers of rock. A class listed what they found in each. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>grass seeds, a grasshopper leg</td></tr>
     <tr><td>middle</td><td>cattail stems, a frog bone, a pond snail</td></tr>
     <tr><td>bottom</td><td>fern fronds, a turtle shell piece</td></tr></table>
     <div class="figure">${F.icon("snail",80)}${F.icon("frog",80)}${F.icon("leaf",80)}</div>`,qs:["Name two organisms that once lived where this ridge now stands.","Was the middle layer once a pond or once dry grassland? Use the fossils as your evidence.","The top layer has grass and a grasshopper and no pond animals. What does that tell you had changed?"],key:["Any two the table names: a grass, a grasshopper, a cattail, a frog, a pond snail, a fern, a turtle. (3-LS4-1)","A pond. Cattails, frogs and pond snails need standing water, and naming them is the evidence. An answer with no fossil named is not yet using the data. (3-LS4-1)","The pond dried up and the place became dry open grassland. The water animals stop appearing and grassland living things start. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Field mice live in the dark soil at the edge of the patch. Owls hunt them at night. A class live-trapped mice, recorded coat color, and marked and released them.</p>
     <table class="bigTable"><tr><th>Mice</th><th>Coat</th><th>Still found after two months, out of 40</th></tr>
     <tr><td>dark brown</td><td>close to the color of the soil</td><td>31</td></tr>
     <tr><td>pale sandy</td><td>stands out against the soil</td><td>9</td></tr></table>`,qs:["Which mice were still around after two months?","Explain why a dark coat is an advantage for a mouse on this dark soil. Use the table.","The dark mice also raised more litters. How can a trait that helps a mouse hide end up giving it more young?"],key:["the dark brown mice, 31 out of 40 against 9 (3-LS4-2)","A dark coat on dark soil is hard for a hunting owl to pick out, so fewer dark mice are caught, 31 still found against 9. The explanation has to lean on the data, and it has to tie the coat to the soil, not just say dark is better. (3-LS4-2)","A mouse that lives longer has more chances to find a mate and raise litters. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:24,title:"The Pond Went Dry",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">The pond at the corner of the patch holds water most years. After a hot dry autumn it shrank to a wet patch of mud. A class checked it every two weeks.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>What happened after the pond shrank</th></tr>
     <tr><td>cattails</td><td>still growing, though fewer new shoots</td></tr>
     <tr><td>pond turtles</td><td>none found anywhere at the pond</td></tr>
     <tr><td>mud snails</td><td>more of them than in any other year</td></tr></table>`,qs:["Which living thing survived well after the pond shrank? Give the evidence.","Which one could not live there at all. Which one managed but not well?","The class wants to pipe water from the farm well into the pond each dry autumn. Would that help the turtles? Name one drawback.","A second plan is to dig one deep end. Then part of the pond always holds water. Which plan has more merit? Why?"],key:["The mud snails. There were more of them than in any other year, so the change suited them. (3-LS4-3)","The pond turtles could not survive there at all, none were found. The cattails survived less well, still growing but with fewer new shoots. (3-LS4-3)","Yes, turtles need standing water and piped water brings it back. Then any real drawback: the well water is needed for the crops, a pump costs money and has to be run by someone, the mud snails that are thriving may be crowded out, it has to be done again every dry year. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: the deep end keeps water without a pump or a person every year, while piping water gives more water but only as long as someone keeps doing it, and the well is needed elsewhere. (3-LS4-4)"]}]},{id:25,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper and hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">Rain measured at the patch in each week of the autumn season.</p>
     <table class="bigTable"><tr><th>Week</th><th>Rain in mm</th></tr>
     <tr><td>1</td><td>5</td></tr><tr><td>2</td><td>10</td></tr><tr><td>3</td><td>30</td></tr>
     <tr><td>4</td><td>45</td></tr><tr><td>5</td><td>50</td></tr><tr><td>6</td><td>60</td></tr></table>
     <div class="figure">${F.icon("rain",88)}${F.icon("pumpkin",88)}</div>`,qs:["What is happening to the rain across the autumn season?","Which half of the season is wetter, the first three weeks or the last three? Use the numbers.","Draw a bar graph of the six weeks. Label both sides."],key:["It is rising week by week, from 5 mm up to 60 mm. (3-ESS2-1)","the last three, 155 mm against 45 mm. Accept a correct comparison even if the student only names the bigger numbers rather than adding them. (3-ESS2-1)","Six bars in week order with heights that match 5, 10, 30, 45, 50 and 60, a label on the week side and a label on the rain side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">Two regions of the world, with their rain split between the two halves of the year.</p>
     <table class="bigTable"><tr><th>Region</th><th>Summer rain</th><th>Winter rain</th><th>Summer temperature</th></tr>
     <tr><td>a coastal region with dry summers</td><td>4 cm</td><td>50 cm</td><td>30 C</td></tr>
     <tr><td>a rainforest region near the middle of the globe</td><td>120 cm</td><td>130 cm</td><td>28 C</td></tr></table>
     <div class="figure">${F.icon("sun",80)}${F.icon("tree",80)}</div>`,qs:["Which region gets rain all year round?","In which region would a farmer have to water crops in summer. What in the table tells you?","Name one reason two regions of the world have different climates."],key:["the rainforest region, 120 cm in summer and 130 cm in winter (3-ESS2-2)","the coastal region with dry summers, because it gets only 4 cm of summer rain (3-ESS2-2)","Any sound reason: how near a region is to the middle of the globe, how high it sits above sea level, how near it is to an ocean, whether mountains block the rain. One solid reason is enough here. (3-ESS2-2)"]},{title:"Ready for the Wind",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">An autumn windstorm can tear the broad vine leaves. It can roll small pumpkins into the ditch. The farmer stacks straw bales two high. They run along the west edge of the field. There are gaps between them.</p>
     <div class="figure">${F.icon("wind",88)}${F.icon("wheat",88)}</div>`,qs:["Which weather hazard is the bale wall meant to reduce?","Make a claim. Does the bale wall have merit? Give your reason.","Name one thing the bale wall does not protect the field from."],key:["wind, which tears the leaves and rolls the fruit (3-ESS3-1)","Yes, with a reason attached: the bales break the force of the wind before it reaches the vines, and the gaps let some air through so the wall is not pushed over. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real limit: heavy rain, frost, hail, wind from another direction, a storm strong enough to topple the bales, bales going soggy and needing replacing. (3-ESS3-1)"]}]},{id:26,title:"Wheelbarrows and Ramps",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">A wheelbarrow loaded with pumpkins stands on the sloped path to the barn. One worker holds the handles and the barrow does not move.</p>
     <div class="figure">${F.icon("pumpkin",96)}${F.icon("hands",80)}</div>`,qs:["The slope pulls the barrow downhill and the worker holds it back. Are the forces on it balanced or unbalanced? How do you know?","The worker shifts her grip and the barrow creeps downhill. What changed about the forces?","Plan an investigation to find out. A worker holds the barrow on the slope. How many pumpkins can it hold before the worker cannot? What will you change? What will you measure?","Name the things you would not let change between runs."],key:["Balanced. She is holding back exactly as hard as the slope pulls, and the barrow standing still is the evidence. (3-PS2-1)","The hold got weaker than the pull of the slope, so the forces became unbalanced and the barrow moved downhill. (3-PS2-1)","A plan with one thing changed and one thing measured: add one pumpkin at a time (the change) and watch for the load at which the barrow first slips from the worker’s hold, or count how many seconds she can hold it (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same barrow, the same worker, the same stretch of path and slope, the same grip, pumpkins of about the same size. (3-PS2-1)"]},{title:"Predict the Next Roll",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">A small pumpkin rolls down a long plank ramp. The class marked where its front edge was after each half second.</p>
     <table class="bigTable"><tr><th>Half seconds</th><th>Distance down the ramp</th></tr>
     <tr><td>1</td><td>10 cm</td></tr><tr><td>2</td><td>40 cm</td></tr><tr><td>3</td><td>90 cm</td></tr><tr><td>4</td><td>160 cm</td></tr></table>`,qs:["Is the pumpkin covering the same distance in every half second, or more each time? Use the numbers.","Look at how much is added each half second: 30, then 50, then 70. What distance would you predict at the fifth half second?","What could happen to the pumpkin that would make your prediction miss?"],key:["More each time. The gaps grow: 10, then 30 more, then 50 more, then 70 more. A pumpkin speeds up as it rolls down. (3-PS2-2)","250 cm, because the next added amount in the pattern is 90, and 160 plus 90 is 250. Accept any answer the student reaches by continuing the pattern and explaining it. (3-PS2-2)","A new force acting on it: the ramp flattens out or ends, the pumpkin hits a bump or a wall, something catches it, it leaves the plank. A pattern only predicts while nothing changes. (3-PS2-2)"]}]},{id:27,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in magnetic interactions between objects not touching",html:()=>`<p class="big">A steel washer sits on top of a wooden table. A magnet is slid along underneath the table top, and the washer slides across the table, following it. The magnet never touches the washer.</p>
     <div class="figure">${F.icon("key",88)}${F.icon("box",80)}</div>`,qs:["The magnet is under the table and the washer is on top. They never touch. What does that tell you about this force?","What two questions could you test to find out more about it?","A plastic button is put on the table in place of the washer and nothing happens. What does that tell you about which materials this force acts on?"],key:["The force acts across a distance and straight through the wood, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how thick can the table be before it stops working, does a stronger magnet pull a heavier washer, does a brass washer follow, how fast can the magnet move before the washer is left behind, does it work through a book. A statement is not a question, so ask once more. (3-PS2-3)","A magnet pulls on steel and iron, not on plastic. The force depends on what the object is made of. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">The patch gate has to swing shut on its own. Then no deer wander in. But the old latch needs two hands. The gate is often left open.</p>
     <div class="figure">${F.icon("deer",88)}${F.icon("key",80)}</div>`,qs:["Put the problem into one sentence beginning: The problem is.","Why is a magnet a sensible idea for a latch? Would a magnet hold a wooden gate post to a wooden gate?","Write two things your latch must do for you to call it a success.","You may use three things only. Two magnets, two steel plates, and four screws. It has to cost under five dollars. What limits does that put on your design?"],key:["A problem statement about a gate latch that shuts and holds on its own without two hands. The problem has to be about the latch, not about the deer. (3-PS2-4)","A magnet pulls steel across a small gap, so the gate can be pulled shut and held closed with no hands and no moving catch. Wood on wood will not work, because a magnet does not pull on wood, so a steel plate has to be fixed to each side. (3-PS2-4)","Two criteria, written as what the latch must do: hold the gate shut against a push, open with one hand, work in rain, not rust, be strong enough that a deer cannot nose it open. (3-5-ETS1-1)","Names the limits as limits: only those materials, only two magnets, under five dollars. Materials, time and cost are the constraints to listen for. (3-5-ETS1-1)"]}]},{id:28,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">Pumpkins have to get from the field to the stand across soft ground. Three ways are tried.</p>
     <table class="bigTable"><tr><th>Design</th><th>Pumpkins per trip</th><th>Sinks into soft ground?</th><th>Pumpkins cracked out of 30</th></tr>
     <tr><td>wheelbarrow</td><td>6</td><td>yes, often</td><td>1</td></tr>
     <tr><td>wide-wheeled wagon</td><td>14</td><td>no</td><td>2</td></tr>
     <tr><td>flat sled dragged by rope</td><td>10</td><td>no</td><td>8</td></tr></table>
     <p class="big">The rules for success: carry at least 10 pumpkins a trip, stay on top of soft ground, crack no more than 3 out of 30.</p>`,qs:["Which design carries the most pumpkins in one trip?","Which design passes all three rules? Explain from the table.","Name a design you would leave out. The rule it fails."],key:["the wide-wheeled wagon, 14 a trip (3-5-ETS1-2)","The wide-wheeled wagon. It carries 14, stays on top of soft ground, and cracks only 2 out of 30. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the wheelbarrow fails the amount rule at 6 and the soft-ground rule, the sled fails the cracking rule at 8. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two wagon wheels were tested to see which one rolls better on soft ground.</p>
     <table class="bigTable"><tr><th>Wheel</th><th>Load in the wagon</th><th>Route</th></tr>
     <tr><td>narrow wheel</td><td>14 pumpkins</td><td>across the soft field</td></tr>
     <tr><td>wide wheel</td><td>6 pumpkins</td><td>along the packed gravel lane</td></tr></table>`,qs:["Can you trust what this test shows? Why or why not?","Name two things that have to match for the test to be fair.","The narrow wheel sank every time the wagon crossed the wet patch by the pond. Name that weak spot. Then say what you would change about the design."],key:["No. Two things were different at once, the load and the route, so sinking cannot be pinned on the wheel. (3-5-ETS1-3)","Any two controlled variables: the same load, the same route, the same distance, the same wagon, the same ground conditions. (3-5-ETS1-3)","The failure point is the narrow wheel sinking in the wet patch. Any improvement aimed at that: fit a wider wheel or a wider tire, lay boards across the wet patch, carry a lighter load over it, route around it. An improvement somewhere else does not count. (3-5-ETS1-3)"]}]},{id:29,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the farm and the land around it. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("tree",54)}<br>woods</td><td>${F.icon("drop",54)}<br>pond</td><td>${F.icon("corn",54)}<br>corn maze</td></tr>
     <tr><th>middle</th><td>${F.icon("mountain",54)}<br>ridge</td><td>${F.icon("pumpkin",54)}<br>pumpkin field</td><td>${F.icon("cabin",54)}<br>barn</td></tr>
     <tr><th>south</th><td>${F.icon("bridge",54)}<br>creek bridge</td><td>${F.icon("bus",54)}<br>parking field</td><td>${F.icon("tractor",54)}<br>farm road</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Distance from the pumpkin field</th></tr>
     <tr><td>barn</td><td>150 m</td></tr><tr><td>pond</td><td>300 m</td></tr>
     <tr><td>corn maze</td><td>400 m</td></tr><tr><td>creek bridge</td><td>650 m</td></tr></table>`,qs:["What lies directly east of the pumpkin field?","Which two directions do you walk to get from the pumpkin field to the corn maze?","Which thing on this map was here before people. Which did people build? Name one of each.","Put the four places in the table in order from nearest to farthest. Which bar would be the tallest on a bar graph?"],key:["the barn (HSS-3.1)","north and east, in either order. The corn maze sits in the north row and the east column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the woods, the pond, the ridge, the creek. Human-made: the pumpkin field, the corn maze, the barn, the bridge, the parking field, the farm road. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.1)","barn, pond, corn maze, creek bridge. The creek bridge bar at 650 m would be the tallest. Partial: the order right with no answer about the bar, or one pair swapped in the order, is approaching. (HSS-3.1)"]}]},{id:30,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how the American Indian nations of California used the plants of their own place long ago, their folklore, and how a nation is part of the state today",html:()=>`<p class="big">Tule is a tall reed. It grows thick along California rivers and marshes. Nations here cut and dried it. They bundled it into boats. Those boats floated two or three people. They used it for mats and for the walls of houses.</p>
      <p class="big">Nations here also kept their own stories. They were told out loud and never written down. They told how the rivers and the animals came to be. They told how the people came to be. Those stories are the nation’s folklore. An elder told them to the children. A child grew up hearing them. That child could tell them in turn.</p>
     <div class="figure">${F.icon("herb",88)}${F.icon("canoe",88)}</div>`,qs:["The screen names one plant and three things nations made from it. Name the plant, say where it grows, and name all three things.","A nation’s folklore was told out loud and not written down. What had to happen in every single generation for those stories to last. What did the stories carry?","Do these nations belong only to the past? Give one way one of them is here today."],key:["Tule, a tall reed, which grows thick along California rivers and marshes. From it nations made boats that floated two or three people, mats, and the walls of houses. Partial: the plant and two of the three things, or all three things with no place named, is approaching. (HSS-3.2)","Somebody had to tell them to the children, and the children had to learn them well enough to tell them later, so the telling had to happen again in every generation. The stories carried the nation’s own account of how the rivers, the animals and the people came to be. Partial: one of the two halves answered is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, people still build tule boats at cultural events, there are language classes and cultural centers, nations care for rivers and land, members live and work across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the town of Creek Landing.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1851</td><td>a ferry starts crossing the creek where the water runs shallow</td></tr>
     <tr><td>1880</td><td>the marsh east of the crossing is drained and planted in grain</td></tr>
     <tr><td>1907</td><td>a bridge replaces the ferry, and a main street grows at its north end</td></tr>
     <tr><td>1946</td><td>a canning plant opens beside the bridge</td></tr>
     <tr><td>1989</td><td>the plant closes and the land becomes a riverside trail</td></tr></table>
      <p class="big">People are still arriving in Creek Landing. In the 1970s and 1980s families came from Vietnam and the Philippines, and more recently from Mexico, India and Ukraine. The town now has a Catholic church, two Protestant churches, a Buddhist temple, a Sikh gurdwara and a small synagogue. The newest grocery on main street sells food from four countries, and three of the town’s doctors grew up somewhere else.</p>`,qs:["Put these three in order, earliest first: the bridge, the ferry, the canning plant.","Which event changed the marsh. What did it do to it?","People are still coming to this town today. Name one place they have come from. Name one place of worship their faith has added. Name one thing newcomers do for the town now."],key:["ferry, bridge, canning plant. Partial: two of the three in the right order is approaching. (HSS-3.3)","the draining in 1880, which turned the marsh into grain fields. Partial: naming the draining with no account of what it did to the marsh is approaching. (HSS-3.3)","From the page. Places people came from: Vietnam, the Philippines, Mexico, India, Ukraine. Places of worship: the Catholic church, a Protestant church, the Buddhist temple, the Sikh gurdwara, the synagogue. What newcomers do for the town: the grocery that sells food from four countries, three of the town’s doctors. One correct answer of each kind is what is being checked. Partial: two of the three kinds given is approaching. (HSS-3.3)"]}]},{id:31,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">The corn maze has a rule on a sign. Stay on the marked paths. The state has a law for a business. The business is open to the public. It must keep a clear way out. That is in case of fire.</p>
      <p class="big">Some Americans took great risks. They did it so other people would be free. Harriet Tubman was born into slavery in Maryland. In 1849 she walked north and reached her own freedom. Then she went back south again and again. She went to guide other people north to freedom. Every trip put her own freedom at risk.</p>
     <div class="figure">${F.icon("flag",88)}${F.icon("books",88)}</div>`,qs:["What is the difference between the maze’s own rule and the state law?","Why do we have laws at all? Give one reason.","The United States government has three parts. Name the part that makes laws and the part that carries them out.","Harriet Tubman had already reached her own freedom. What did she put at risk by going back. Why does that make her an American hero?"],key:["The maze rule is set by the farm and applies in the maze. The state law is made by a government, applies to every business in the state, and the government decides what happens when it is broken. Partial: describing the maze rule with nothing said about who makes the state law is approaching. (HSS-3.4)","Any sound reason: to keep people safe, to settle disagreements fairly, so everyone knows what to expect, to protect people’s things and rights. Partial: saying laws are the rules with no reason for having them is approaching. (HSS-3.4)","the legislative branch, Congress, makes the laws, and the executive branch, led by the President, carries them out. Partial: one of the two parts named is approaching. (HSS-3.4)","She put her own freedom at risk every time she went back. She counts as an American hero because she took that risk for other people’s freedom and not for her own. Accept any wording that holds both parts. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the price list. Answer out loud.",desc:"basic economic reasoning about scarce money, trade-offs, goods and services",html:()=>`<p class="big">The farm sells pumpkins and cider at the stand, and it also sells rides on the hay wagon. A family comes with 20 dollars.</p>
     <table class="bigTable"><tr><th>What they want</th><th>Price</th></tr>
     <tr><td>a large pumpkin</td><td>9 dollars</td></tr><tr><td>a jug of cider</td><td>7 dollars</td></tr>
     <tr><td>two hay wagon rides</td><td>8 dollars</td></tr></table>
      <p class="big">Not everything at the stand was made here. The pumpkins and the cider come from this farm. The paper bags come from a factory in Ohio. The string lights over the table were made in China.</p>`,qs:["Can the family buy all three with 20 dollars? Work it out.","They decide on the pumpkin and the cider. What have they given up. What is the name for the thing you give up when you choose?","A pumpkin and a hay wagon ride are different kinds of thing. Which is a good and which is a service?","Some goods are made right here. Some come from elsewhere in the United States. Some come from another country. Give one example of each from the stand."],key:["No. 9 plus 7 plus 8 is 24 dollars, and they have 20. Partial: saying no with no total worked out is approaching. (HSS-3.5)","They gave up the two hay wagon rides. The idea is a trade-off, or opportunity cost: picking one thing means doing without another, because money is limited. The idea matters more than the term at this grade. Partial: naming what was given up with no idea of a trade-off, or the term with nothing given up named, is approaching. (HSS-3.5)","A pumpkin is a good, something you can hold. A hay wagon ride is a service, something someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Made here: the pumpkins or the cider. Elsewhere in the United States: the paper bags, from Ohio. Another country: the string lights, from China. All three are what is being checked. Partial: two of the three kinds given is approaching. (HSS-3.5)"]}]}];const WC=MAZE.split(/\s+/).filter(Boolean).length;STOPS[2].parts[0].n=WC;STOPS[2].parts[0].key[0]=STOPS[2].parts[0].key[0].replace("__WC__",WC);STOPS[2].parts[0].desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={2:{id:"L2",title:"Level Up: Big Crowd Rounding",std:["4.NBT.A.3"],needs:["3.NBT.A.1"],n:3,dir:"Say each answer out loud.",html:()=>`<p class="big" style="text-align:center">The fall fair had this many visitors:</p><p class="huge" style="font-size:clamp(3rem,10vw,6rem)">7,846</p><ol class="qlist"><li>Round to the nearest thousand.</li><li>Round to the nearest hundred.</li><li>Round to the nearest ten.</li></ol>`,key:["8,000 (4.NBT.A.3)","7,800 (4.NBT.A.3)","7,850 (4.NBT.A.3)"]},4:{id:"L4",title:"Level Up: Read Between the Rows",std:["RL.4.1"],needs:["RL.3.1"],n:1,dir:"Answer out loud. Use details from the story.",html:()=>`<p class="big">At the end, Rosa laughs and says, “Five minutes?” Why does she say that? Give two details from the story that help you know.</p>${F.passage(MAZE,MAZE_TITLE,true)}`,key:["She is teasing Dev, because he was sure they would be out in five minutes and it took much longer. Two details, such as: Dev said, “We will be out in five minutes,” they went in at two o’clock and came out at three o’clock, they went in circles, they hit two dead ends. The story does not say why she laughs, so this is an inference. (RL.4.1, inference with details)"]},9:{id:"L9",title:"Level Up: Sun Detective",std:["RI.4.1"],needs:["RI.3.1"],n:1,dir:"Answer out loud. Use details from the text.",html:()=>`<p class="big">It is noon, and the sun is high in the middle of the sky. Which way do you think a young sunflower bud is facing? Give details from the text that help you know.</p>${F.passage(SUN,SUN_TITLE,true)}`,key:["Up toward the middle of the sky, about halfway between east and west. Details: the bud faces east in the morning, it turns all day to follow the sun, and it faces west by evening. The text never says what happens at noon, so the student has to put the details together. (RI.4.1, inference with details)"]},10:{id:"L10",title:"Level Up: Fence the Patch",std:["4.MD.A.3"],needs:["3.MD.C.7"],n:2,dir:"Solve on your paper and hold it up.",html:()=>`<div class="figure">${fenceRect()}</div><ol class="qlist"><li>This pumpkin patch has an area of 63 square meters. It is 9 meters long. How wide is it?</li><li>A fence goes all the way around the patch. How long is the fence?</li></ol>`,key:["7 meters, from 63 ÷ 9 or 9 × ? = 63 (4.MD.A.3, area formula with an unknown side)","32 meters, from 9 + 7 + 9 + 7 or 2 × (9 + 7) (4.MD.A.3, perimeter)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","W.3.8","RL.4.1","RI.4.1"];const MULT_N=10;const PV_COLS=["Thousands","Hundreds","Tens","Ones"];let multSel=[0,0],pvVal="";function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(){const ip=pvVal.replace(/[^0-9]/g,"").slice(-PV_COLS.length);let h="<tr>";PV_COLS.forEach(c=>h+=`<th>${c}</th>`);h+="</tr><tr>";PV_COLS.forEach((c,i)=>{const k=ip.length-(PV_COLS.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});return h+"</tr>"}function pvHtml(){return`<label class="pv-in">Type a number<input type="text" inputmode="numeric" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div>`}function starters(st){if(st.std.includes("W.3.1"))return["I would rather ____.","One reason is ____.","Another reason is ____.","That is why ____."];if(st.std.includes("SL.3.4"))return["I want to tell you about ____.","First, ____.","One thing I remember is ____.","It looked (or sounded, or felt) like ____.","That is why ____."];if(st.std.includes("W.3.3"))return["One fall day, ____.","First, ____.","Next, ____.","“____,” I said.","Finally, ____."];return["This is how a pumpkin grows.","First, ____.","Next, ____.","After that, ____.","In the end, ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.MD.C.7","3.OA.A.1","3.OA.A.2","3.OA.D.8","4.MD.A.3"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},pv:{name:"Place value chart",std:["3.NBT.A.1","4.NBT.A.3","3.OA.D.8"],html:pvHtml,bind:b=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9,]/g,"");tb.innerHTML=pvTable()}}},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3","SL.3.4"],html:sentHtml}};const SUP_CAVEATS=[{t:"mult",std:["3.MD.C.7","4.MD.A.3"],msg:"The multiplication chart gives the products. Rate on whether the student knows which numbers to multiply or add to find the area."},{t:"mult",std:["3.OA.D.8"],msg:"The multiplication chart gives the facts. Rate on the equation, the two steps, and the estimate."},{t:"sent",std:["W.3.2","W.3.3"],msg:"Sentence starters supply the linking or time words and the closing, so count those checks as supported, not independent."},{t:"sent",std:["SL.3.4"],msg:"Sentence starters give the student the order of the talk. Rate the facts, the details, and how clearly the student speaks."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1","RI.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"sent",std:["W.3.1"],msg:"The starters supply the linking words and the closing line, so count those two checks as supported, not independent."},{t:"mult",std:["3.OA.A.1","3.OA.A.2"],msg:"The chart gives the product and the quotient. Rate on whether the student can say what the numbers mean in the crate, not on the answer."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
